\chapter{Games, strategies, and conditionally linear distributions}
\label{chap:qpbt-games}
% Paper label sec:games kept for cross-reference fidelity; resolves to the chapter number.
\label{sec:games}

This chapter records the vocabulary in which the quantum Pauli basis test and its analysis are phrased: two-player one-round games and tensor product strategies, the consistency and state-dependent distance calculus for families of measurements, and conditionally linear functions and distributions, the class of question distributions used by the tests of Chapter~\ref{chap:qpbt-test}. The presentation follows \cite{Ji2020MIPStar}; the distance calculus is imported there from \cite{Natarajan2018NEEXP} and \cite{Ji2020LowIndividualDegree}.

\section{Measurements and observables}

\begin{definition}[POVMs, sub-measurements, and observables]\label{def:povm-conventions}
	\uses{def:submeasurement}
	% Finiteness of the outcome set is stated explicitly here; the source leaves it implicit,
	% and the measurement and submeasurement definitions referenced below assume finite
	% outcome sets.
	Quantum measurements are modeled as positive operator-valued measures (POVMs). A \emph{POVM} on a finite-dimensional Hilbert space $\mathcal H$ is a family of positive semidefinite operators $\{M_a\}_{a \in S}$ indexed by outcomes $a$ ranging over a finite set $S$ such that $\sum_a M_a = \Id$; if the latter condition is relaxed to $\sum_a M_a \le \Id$, then $\{M_a\}$ is a \emph{sub-measurement}. (POVMs and sub-measurements are thus exactly the measurements and submeasurements of Definition~\ref{def:submeasurement}.) The probability that the measurement returns outcome $a$ on a state $\ket{\psi}$ is
	\[
		\Prb(a) = \bra{\psi} M_a \ket{\psi}\,.
	\]
	A POVM $M = \{M_a\}$ is \emph{projective} if each operator $M_a$ is a projector ($M_a^2 = M_a$); this automatically implies that $M_a M_b = M_b M_a = 0$ for distinct outcomes $a \ne b$. An \emph{observable} is a unitary matrix. A \emph{binary observable} is an observable $O$ such that $O^2 = \Id$, i.e.\ $O$ has eigenvalues in $\{-1,1\}$.

	Subscripts of a measurement index the outcome, and superscripts index different measurements. When the outcome of a measurement $\{M^x_{a,\,b}\}$ consists of two parts $a$ and $b$, we write $\{M^x_a\}$ and $\{M^x_b\}$ for its \emph{marginals}
	\[
		M^x_a = \sum_b M^x_{a,\,b}\,, \qquad M^x_b = \sum_a M^x_{a,\,b}\,;
	\]
	for every $x$ both marginals are again POVMs.
\end{definition}

\begin{definition}[Bracket notation for post-processed measurements]\label{def:bracket}
	\lean{MIPStarRE.Quantum.Measurement.postprocess}
	\leanok
	\uses{def:povm-conventions, def:post-processing}
	Let $\mathcal A$ and $\mathcal B$ be finite sets, let $\{M^x_a\}_{a \in \mathcal A}$ be a family of POVMs indexed by $x \in \mathcal X$, and let $f \colon \mathcal A \to \mathcal B$ be an arbitrary function. We write $\bigl\{ M^x_{[f(\cdot)=b]} \bigr\}$ for the POVM derived from $\{M^x_a\}$ by applying the function $f$ to the outcome before returning it:
	\[
		M^x_{[f(\cdot)=b]} = \sum_{a\,:\,f(a)=b} M^x_a\,,
	\]
	and $M^x_{[f(\cdot)=b]} = 0$ when $b$ is not in the image of $f$. When the outcome $a$ has a natural interpretation as a tuple $(a_1,\dots,a_k)$, we also write, for $i \in \{1,\dots,k\}$,
	\[
		M^x_{[a_i=b]} = \sum_{(a_1,\dots,a_k)\,:\,a_i=b} M^x_{(a_1,\dots,a_k)}\,.
	\]
	For each fixed $x$ this is the post-processing operation of Definition~\ref{def:post-processing}.
\end{definition}

\begin{remark}[Naimark dilation for strategies]\label{rem:naimark-for-games}
	The symmetrization argument of Lemma~\ref{lem:symmetric-strat} below invokes Naimark dilation in the form of Theorem~\ref{thm:naimark} (stated and proved in Chapter~\ref{chap:projective}): a bipartite state together with two sub-measurement families can be replaced, without changing any of the correlations $\bra{\psi} A^x_a \ot B^y_b \ket{\psi}$, by a product-extended state together with projective sub-measurements on the enlarged spaces. When the input families are complete measurements, the dilated projective sub-measurements can be completed by assigning the residual projector of each family to one fixed outcome; the resulting projective measurements reproduce the same correlations on the extended state, since the correlation-preservation identity forces the extended state to lie in the range of the total projector of each dilated family. This completed form, with genuinely projective measurements, is the one used in Lemma~\ref{lem:symmetric-strat}; for the proof the source refers to Theorem 5.1 of \cite{Ji2020LowIndividualDegree}, which is stated for complete measurements. The source follows its statement of the dilation theorem with a sentence announcing an ``orthogonalization lemma'' from the literature that is never actually stated there; nothing in this chapter depends on it.
\end{remark}

\section{Games and strategies}
% Paper subsection label sec:strat kept for cross-reference fidelity.
\label{sec:strat}

\begin{definition}[Two-player one-round games]\label{def:game}
	A \emph{two-player one-round game} $\mathfrak G$ is specified by a tuple $(\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ where
	\begin{enumerate}
		\item $\mathcal X$ and $\mathcal Y$ are finite sets, called the \emph{question alphabets},
		\item $\mathcal A$ and $\mathcal B$ are finite sets, called the \emph{answer alphabets},
		\item $\mu$ is a probability distribution over $\mathcal X \times \mathcal Y$, called the \emph{question distribution}, and
		\item $D \colon \mathcal X \times \mathcal Y \times \mathcal A \times \mathcal B \to \{0,1\}$ is a function, called the \emph{decision predicate}.
	\end{enumerate}
\end{definition}

\begin{definition}[Tensor product strategies]\label{def:tensor-product-strategy}
	\uses{def:game, def:povm-conventions}
	A \emph{tensor product strategy} $\mathcal S$ for a game $\mathfrak G = (\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ is a tuple $(\ket{\psi}, A, B)$ where
	\begin{itemize}
		\item $\ket{\psi}$ is a pure quantum state, i.e.\ a unit vector in $\mathcal H_A \ot \mathcal H_B$ for finite-dimensional complex Hilbert spaces $\mathcal H_A$, $\mathcal H_B$,
		\item $A$ is a set $\{A^x\}$ such that for every $x \in \mathcal X$, $A^x = \{A^x_a\}_{a \in \mathcal A}$ is a POVM on $\mathcal H_A$, and
		\item $B$ is a set $\{B^y\}$ such that for every $y \in \mathcal Y$, $B^y = \{B^y_b\}_{b \in \mathcal B}$ is a POVM on $\mathcal H_B$.
	\end{itemize}
\end{definition}

\begin{definition}[Tensor product value]\label{def:tensor-product-value}
	\uses{def:tensor-product-strategy}
	The \emph{tensor product value} of a tensor product strategy $\mathcal S = (\ket{\psi}, A, B)$ with respect to a game $\mathfrak G = (\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ is
	\[
		\operatorname{val}^*(\mathfrak G, \mathcal S) = \sum_{x,\,y,\,a,\,b} \mu(x,y)\, D(x,y,a,b)\, \bra{\psi} A^x_a \ot B^y_b \ket{\psi}\,.
	\]
	For $v \in [0,1]$ we say that the strategy $\mathcal S$ \emph{passes (or wins) $\mathfrak G$ with probability $v$} if $\operatorname{val}^*(\mathfrak G, \mathcal S) \ge v$. The \emph{tensor product value} of $\mathfrak G$ is
	\[
		\operatorname{val}^*(\mathfrak G) = \sup_{\mathcal S} \operatorname{val}^*(\mathfrak G, \mathcal S)\,,
	\]
	where the supremum is taken over all tensor product strategies $\mathcal S$ for $\mathfrak G$.
\end{definition}

Unless specified otherwise, all strategies considered in what follows are tensor product strategies, and we simply call them \emph{strategies}; similarly, we refer to $\operatorname{val}^*(\mathfrak G)$ as the \emph{value} of the game $\mathfrak G$.

% The source labels this definition def:projective-strategy. That label is already carried
% by the low individual degree test track (Chapter 2), where it names the strategy format
% specific to that test, so a distinct label is used here; see the following remark.
\begin{definition}[Projective strategies]\label{def:projective-strategy-general}
	\uses{def:tensor-product-strategy, def:povm-conventions}
	A strategy $\mathcal S = (\ket{\psi}, A, B)$ is \emph{projective} if all the measurements $\{A^x_a\}_a$ and $\{B^y_b\}_b$ are projective.
\end{definition}

\begin{remark}[Two uses of the term ``projective strategy'']\label{rem:projective-strategy-relation}
	Definition~\ref{def:projective-strategy-general} is the general notion: a strategy for an arbitrary nonlocal game all of whose measurements are projective. The low individual degree chapters use the same term for the concrete data of a two-prover strategy for the $(m,q,d)$ low individual degree test (Definition~\ref{def:projective-strategy} in Chapter~\ref{chap:test}); that definition is the specialization of the present notion to the question format of that particular test. The two usages occur in disjoint contexts.
\end{remark}

\begin{definition}[Symmetric games and symmetric strategies]\label{def:symmetric-game}
	% Paper label: rem:symmetric-games (a definition environment carrying a rem: label in the
	% source); relabeled here to match the environment kind.
	\uses{def:game, def:tensor-product-strategy}
	A game $\mathfrak G = (\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ is \emph{symmetric} if the question and answer alphabets are the same for both players (i.e.\ $\mathcal X = \mathcal Y$ and $\mathcal A = \mathcal B$), the distribution $\mu$ is symmetric (i.e.\ $\mu(x,y) = \mu(y,x)$ for all $x,y$), and the decision predicate $D$ treats both players symmetrically (i.e.\ $D(x,y,a,b) = D(y,x,b,a)$ for all $x,y,a,b$).

	A strategy $\mathcal S = (\ket{\psi}, A, B)$ is \emph{symmetric} if $\ket{\psi}$ is a (pure) state in $\mathcal H \ot \mathcal H$, for some Hilbert space $\mathcal H$, that is invariant under permutation of the two factors, and the measurement operators of both players are identical.
\end{definition}

We often specify symmetric games $\mathfrak G$ and symmetric strategies $\mathcal S$ using a compact notation: we write $\mathfrak G = (\mathcal X, \mathcal A, \mu, D)$ and $\mathcal S = (\ket{\psi}, M)$, where $M$ denotes the set of measurement operators shared by both players.

% Source statement (references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:94-99) kept in
% its original form. The proof below records the approximate form the source argument
	\uses{def:consistent-measurement, def:projective-strategy-general}
	Let $\mathcal S = (\ket{\psi}, A, B)$ be a projective strategy with state $\ket{\psi} \in \mathcal H \ot \mathcal H$, for some Hilbert space $\mathcal H$, defined on question alphabets $\mathcal X$ and $\mathcal Y$ and answer alphabets $\mathcal A$ and $\mathcal B$, respectively. We say that $\mathcal S$ is \emph{consistent} if for all $x \in \mathcal X$ the measurement $\{A^x_a\}_{a \in \mathcal A}$ is consistent on $\ket{\psi}$, and for all $y \in \mathcal Y$ the measurement $\{B^y_b\}_{b \in \mathcal B}$ is consistent on $\ket{\psi}$.
\end{definition}

We almost always restrict attention to symmetric strategies; in this case consistency implies that whenever both players are sent the same question, they provide the same answer.

\begin{definition}[PCC and SPCC strategies]\label{def:spcc}
	\uses{def:projective-strategy-general, def:consistent-strategy, def:comm-strategy, def:symmetric-game}
	We say that a strategy $\mathcal S$ for a game $\mathfrak G$ is \emph{PCC} if it is projective, consistent, and commuting for $\mathfrak G$. Additionally, we say that a PCC strategy $\mathcal S$ is \emph{SPCC} if it is furthermore symmetric.
\end{definition}

\section{Distance measures}

\begin{definition}[Distance between states]\label{def:state-distance}
	Let $\{\ket{\psi_n}\}_{n \in \N}$ and $\{\ket{\psi'_n}\}_{n \in \N}$ be two families of states in the same space $\mathcal H$. For a function $\delta \colon \N \to [0,1]$ we say that $\{\ket{\psi_n}\}$ and $\{\ket{\psi'_n}\}$ are \emph{$\delta$-close}, denoted $\ket{\psi} \approx_\delta \ket{\psi'}$, if
	\[
		\lVert \ket{\psi_n} - \ket{\psi'_n} \rVert^2 = O(\delta(n))\,.
	\]
	The dependence of the states and of $\delta$ on the indexing parameter $n$ is generally left implicit; we write, e.g., $\ket{\psi}$ for $\ket{\psi_n}$.
\end{definition}

\begin{definition}[Consistency between POVMs]\label{def:consistency}
	\uses{def:povm-conventions, def:state-distance}
	Let $\mathcal X$ be a finite set and $\mu$ a distribution on $\mathcal X$. Let $\ket{\psi} \in \mathcal H_A \ot \mathcal H_B$ be a quantum state, and for all $x \in \mathcal X$ let $\{A^x_a\}$ and $\{B^x_a\}$ be POVMs. We write
	\[
		A^x_a \ot \Id_B \simeq_\delta \Id_A \ot B^x_a
	\]
	on state $\ket{\psi}$ and distribution $\mu$ if
	\[
		\E_{x \sim \mu} \sum_{a \ne b} \bra{\psi} A^x_a \ot B^x_b \ket{\psi} = O(\delta)\,.
	\]
	In this case we say that $\{A^x_a\}$ and $\{B^x_a\}$ are \emph{$\delta$-consistent} on $\ket{\psi}$. As in Definition~\ref{def:state-distance}, the $O(\cdot)$ refers to families of POVMs and states indexed by an implicit parameter $n \in \N$, and is taken as $n \to \infty$.
\end{definition}

A measurement that is consistent on $\ket{\psi}$ in the sense of Definition~\ref{def:consistent-measurement} is $0$-consistent with itself on the same state under the singleton distribution, and vice versa: if $\sum_a \bra{\psi} M_a \ot M_a \ket{\psi} = 1$, then $M_a \ot \Id\, \ket{\psi} = \Id \ot M_a\, \ket{\psi}$ for every $a$, by the equality case of the Cauchy--Schwarz inequality applied outcome by outcome.

% The source (references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:257-274) states this
% definition for pairs of POVMs but applies the relation to arbitrary operator families:
% to plain operators at 06:313-330, to sets of matrices at 06:364-380, and to products and
% commutators, compared against the zero family, at 06:409-445. The general form below,
% for arbitrary finite families of operators, is the one of the NEEXP source
% (references/neexp-paper/05_quantum_preliminaries.tex:385-391), from which the distance
% calculus is imported; the POVM case is singled out after the display.
\begin{definition}[State-dependent distance between operator families]\label{def:povm-distance}
	\uses{def:povm-conventions, def:state-distance}
	Let $\mathcal X$ and $\mathcal A$ be finite sets and $\mu$ a distribution on $\mathcal X$. Let $\ket{\psi} \in \mathcal H$ be a quantum state, and for all $x \in \mathcal X$ let $\{M^x_a\}_{a \in \mathcal A}$ and $\{N^x_a\}_{a \in \mathcal A}$ be two families of linear operators on $\mathcal H$. We say that \emph{$\{M^x_a\}$ and $\{N^x_a\}$ are $\delta$-close on state $\ket{\psi}$ and under distribution $\mu$} if
	\[
		\E_{x \sim \mu} \sum_a \lVert (M^x_a - N^x_a)\, \ket{\psi} \rVert^2 \le O(\delta)\,,
	\]
	and we write $M^x_a \approx_\delta N^x_a$ to denote this when the state $\ket{\psi}$ and the distribution $\mu$ are clear from context. This distance is referred to as the \emph{state-dependent} distance. The principal case is that in which $\{M^x_a\}$ and $\{N^x_a\}$ are POVMs on $\mathcal H$, and we then speak of the state-dependent distance between the POVMs; but the relation is used for arbitrary operator families --- for instance for products of measurement operators, or for commutators compared against the identically zero family, as in Lemma~\ref{lem:commutation-analysis} below.
\end{definition}

\begin{definition}[Distance between strategies]\label{def:strategy-distance}
	\uses{def:tensor-product-strategy, def:state-distance, def:povm-distance}
	Let $\mathfrak G = (\mathcal X, \mathcal Y, \mathcal A, \mathcal B, \mu, D)$ be a nonlocal game and let $\mathcal S = (\psi, A, B)$ and $\mathcal S' = (\psi', A', B')$ be strategies for $\mathfrak G$. For $\delta \in [0,1]$ we say that \emph{$\mathcal S$ is $\delta$-close to $\mathcal S'$} if the following conditions hold.
	\begin{enumerate}
		\item The states $\ket{\psi}, \ket{\psi'}$ are states in the same Hilbert space $\mathcal H_A \ot \mathcal H_B$ and are $\delta$-close.
		\item For all $x \in \mathcal X$ and $y \in \mathcal Y$, we have $A^x_a \approx_\delta (A')^x_a$ and $B^y_b \approx_\delta (B')^y_b$, with the approximations holding under the distribution $\mu$ (i.e.\ under its corresponding marginals), on either $\ket{\psi}$ or $\ket{\psi'}$.
	\end{enumerate}
\end{definition}

\begin{remark}[Asymptotic reading of the distance relations]\label{rem:asymptotic-distance}
	Definitions~\ref{def:state-distance}, \ref{def:consistency}, and \ref{def:povm-distance} are asymptotic: every $\approx_\delta$ and $\simeq_\delta$ statement refers to families of states and measurement families indexed by an implicit parameter $n \in \N$, and the $O(\cdot)$ is taken as $n \to \infty$. None of these relations is a pointwise inequality with an explicit constant. By contrast, the corresponding relations used in the low individual degree chapters (Definitions~\ref{def:simeq} and~\ref{def:approx_delta}) carry no hidden constant. Any explicit quantitative version of the present relations therefore retains the constants absorbed into the $O(\cdot)$; for instance, the triangle inequality of Lemma~\ref{fact:triangle} carries a factor $2$ inside the $O(\cdot)$.
\end{remark}

We record several useful facts about the consistency measure and the state-dependent distance. For the statements imported without proof, readers are referred to Sections~4.4 and~4.5 of \cite{Natarajan2018NEEXP}.

\begin{lemma}[Consistency versus closeness; Facts 4.13 and 4.14 in \cite{Natarajan2018NEEXP}]\label{fact:agreement}
	\uses{def:consistency, def:povm-distance}
	For POVMs $\{A^x_a\}$ and $\{B^x_a\}$, the following hold.
	\begin{enumerate}

	% by the sampling procedure the actual contents are the canonical pairs (u_0, s) and
	% triples (u_0, s, v') with v' = pi_{i-1}(v). We state the canonical form.
	\begin{itemize}
		\item $(\mathsf{Point},W)$: content $y \in \F_q^m$; answer an element of $\F_q$.
		\item $(\mathsf{ALine},W)$: content $(u_0, s) \in \F_q^m \times \F_q$; answer a univariate polynomial $f\colon \F_q \to \F_q$ of degree at most $d$.
		\item $(\mathsf{DLine},W)$: content $(u_0, s, v') \in \F_q^m \times \F_q \times \F_q^m$; answer a univariate polynomial $f\colon \F_q \to \F_q$ of degree at most $md$.
		\item $\mathsf{Pair}$: content $\omega = (u_X, u_Z, r_X, r_Z) \in (\F_q^m)^2 \times \F_q^2$; answer $(\beta_X, \beta_Z) \in \F_2^2$.
		\item $(\mathsf{Pair},W)$: content $\omega$ as above; answer an element of $\F_2$.
		\item $\mathsf{Constraint}_i$: content $\omega$ as above; answer $(\alpha_{v_1}, \alpha_{v_2}, \alpha_{v_3}) \in \F_2^3$, indexed by the variable indices $(v_1,v_2,v_3)$ of $\mathsf{Constraint}_i$.
		\item $\mathsf{Variable}_j$: content $\omega$ as above; answer an element of $\F_2$.
		\item $(\mathsf{Pauli},W)$: content $0$; answer an element of $\F_q^M$.
	\end{itemize}
	The win predicate $D^{\mathrm{pauli}} = D^{\mathrm{pauli}}_{\mathsf{qldparams}}$ is the function of the tuple $(t_{\mathrm A}, x_{\mathrm A}, t_{\mathrm B}, x_{\mathrm B}, a_{\mathrm A}, a_{\mathrm B})$ determined by the following clauses, evaluated for $w \in \{\mathrm A, \mathrm B\}$ and $W \in \{X,Z\}$; in all cases where no action is indicated, the predicate accepts. In the last four clauses, the content of the player whose type lies in $\mathcal T^{\mathrm{ms}} \cup \{\mathsf{Pair}, (\mathsf{Pair},X), (\mathsf{Pair},Z)\}$ is a tuple $(u_X, u_Z, r_X, r_Z)$, from which the predicate first computes
	\begin{equation}
		\label{eq:gamma-value}
		\gamma = \tr\bigl( (\mathrm{ind}_m(u_X) \cdot r_X) \cdot (\mathrm{ind}_m(u_Z) \cdot r_Z) \bigr) \in \F_2\;,
	\end{equation}
	where $\mathrm{ind}_m(\cdot) \in \F_q^M$ is the indicator vector of the low-degree encoding (Chapter~\ref{chap:qpbt-algebra}), the inner dot denotes the dot product on $\F_q^M$, and $\tr\colon \F_q \to \F_2$ is the finite-field trace.
	\begin{enumerate}
		\item (\textbf{Consistency check}) If $t_{\mathrm A} = t_{\mathrm B}$, accept if and only if $a_{\mathrm A} = a_{\mathrm B}$.
		\item (\textbf{Low-degree check}) Let $\mathsf{ldparams} = (q,m,d,1)$; admissibility of $\mathsf{qldparams}$ gives $d \ge 1$ and $m \mid q$, so this is a parameter tuple as in Definition~\ref{def:ld-game}.
		\begin{enumerate}
			\item If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = (\mathsf{ALine},W)$, accept if $D^{\mathrm{ld}}_{\mathsf{ldparams}}$ accepts $(\mathsf{Point}, x_w, \mathsf{ALine}, x_{\overline w}, a_w, a_{\overline w})$.
			\item If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = (\mathsf{DLine},W)$, accept if $D^{\mathrm{ld}}_{\mathsf{ldparams}}$ accepts $(\mathsf{Point}, x_w, \mathsf{DLine}, x_{\overline w}, a_w, a_{\overline w})$.
		\end{enumerate}
		\item (\textbf{Consistency check}) If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = (\mathsf{Pauli},W)$, accept if $g_{a_{\overline w}}(x_w) = a_w$, where $g_{a_{\overline w}}$ is the low-degree encoding of $a_{\overline w} \in \F_q^M$ (Chapter~\ref{chap:qpbt-algebra}).
		\item (\textbf{Commutation check}) If $t_w = (\mathsf{Pair},W)$ and $t_{\overline w} = \mathsf{Pair}$, accept if $a_w = \beta_W$ or $\gamma \neq 0$.
		\item (\textbf{Consistency check}) If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = (\mathsf{Pair},W)$, accept if $\tr(a_w r_W) = a_{\overline w}$ or $\gamma \neq 0$.
		\item (\textbf{Magic Square check}) If $t_w = \mathsf{Constraint}_i$ and $t_{\overline w} = \mathsf{Variable}_j$, accept if $\gamma = 0$, or if $a_w$ satisfies the equation of $\mathsf{Constraint}_i$ and $\alpha_j = a_{\overline w}$.
		\item (\textbf{Consistency check}) If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = \mathsf{Variable}_j$, accept if $\gamma = 0$, or if $j = 1$, $W = X$, and $\tr(a_w r_X) = a_{\overline w}$, or if $j = 5$, $W = Z$, and $\tr(a_w r_Z) = a_{\overline w}$.
	\end{enumerate}
	The game $\mathfrak{G}^{\mathrm{Pauli}}_{\mathsf{qldparams}}$ is the typed game with type set $\mathcal T^{\mathrm{pauli}}$, the question distribution of Definition~\ref{def:pauli-question-distribution}, and win predicate $D^{\mathrm{pauli}}_{\mathsf{qldparams}}$.
\end{definition}

Note the one-sided gating on $\gamma$: the commutation check and the $\mathsf{Pair}$ consistency check accept automatically when $\gamma \neq 0$, while the Magic Square check and the $\mathsf{Variable}$ consistency check accept automatically when $\gamma = 0$.

\begin{lemma}[Completeness of the Pauli basis test]\label{lem:pauli-completeness}
	\uses{def:pauli-question-distribution, def:pauli-win-predicate, def:admissible, def:spcc, def:tensor-product-value}
	For every admissible tuple $\mathsf{qldparams} = (q,m,d)$ (Definition~\ref{def:admissible}), the Pauli basis test $\mathfrak{G}^{\mathrm{Pauli}}_{\mathsf{qldparams}}$ has a value-$1$ SPCC strategy.
\end{lemma}
\begin{proof}
	\uses{thm:ms-from-ac, def:pauli-win-predicate, def:bracket, def:consistent-measurement, def:EPR, def:indicator-vector, lem:pauli-observable-expansion, lem:twisted-commutation}
	The strategy uses the state $\ket{\psi} = \ket{\mathrm{EPR}_q}^{\ot M} \ot \ket{\mathrm{EPR}_2}$ with $M = 2^m$. On a question $((\mathsf{Point},W), y)$ a player measures the generalized Pauli basis POVM $\{\tau^W_h\}_{h \in \F_q^M}$ and reports $g_h(y)$; on $((\mathsf{ALine},W), \ell)$ or $((\mathsf{DLine},W), \ell)$ they report the restriction of $g_h$ to the line $\ell$, expressed as a univariate polynomial through the canonical parameterization of $\ell$; and on $(\mathsf{Pauli},W)$ they report $h$ itself --- in the bracket notation of Definition~\ref{def:bracket}, these measurements are $\tau^W_{[g_\cdot(y) = a]} \ot I$, $\tau^W_{[(g_\cdot)|_\ell = f]} \ot I$, and $\tau^W_a \ot I$. For a content $\omega = (u_X, u_Z, r_X, r_Z)$, consider the two binary measurements $A_b = \tau^X_{[\tr(g_\cdot(u_X)\, r_X) = b]} \ot I$ and $B_b = \tau^Z_{[\tr(g_\cdot(u_Z)\, r_Z) = b]} \ot I$. Since $g_h(u) = h \cdot \mathrm{ind}_m(u)$ (Chapter~\ref{chap:qpbt-algebra}), the relation between the Pauli projections and observables gives $\mathcal O_A = A_0 - A_1 = \tau^X(\mathrm{ind}_m(u_X)\, r_X) \ot I$ and $\mathcal O_B = \tau^Z(\mathrm{ind}_m(u_Z)\, r_Z) \ot I$, and the twisted commutation relation yields
	\[
		\mathcal O_A \mathcal O_B = (-1)^\gamma\, \mathcal O_B \mathcal O_A
	\]
	with $\gamma$ as in Equation~\eqref{eq:gamma-value}: the two measurements commute when $\gamma = 0$ and anticommute when $\gamma = 1$. If $\gamma = 0$, define $E^{\mathsf{Pair},\omega}_{\beta_X,\beta_Z} = A_{\beta_X} B_{\beta_Z}$ and $E^{(\mathsf{Pair},X),\omega}_a = A_a$, $E^{(\mathsf{Pair},Z),\omega}_a = B_a$, and let the $\mathsf{Constraint}$ and $\mathsf{Variable}$ measurements be trivial (identity on the all-zeros outcome). If $\gamma = 1$, let the $\mathsf{Constraint}$ and $\mathsf{Variable}$ measurements be those produced by Theorem~\ref{thm:ms-from-ac} from the anticommuting consistent pair $(A, B)$, acting on the auxiliary $\ket{\mathrm{EPR}_2}$ factor, and let the $\mathsf{Pair}$ measurements be trivial. The strategy is symmetric and projective by construction; every measurement is either a post-processed Pauli basis measurement, a measurement supplied by Theorem~\ref{thm:ms-from-ac}, or (in the $\gamma = 0$ case) a product of two commuting consistent measurements, so the strategy is consistent, and commutativity along every edge of $G^{\mathrm{pauli}}$ is checked case by case --- for instance, $(\mathsf{Point},X)$ and $\mathsf{Variable}_1$ commute because both are $X$-basis measurements. Consistency and projectivity give the consistency checks with certainty, and the low-degree checks pass because the answers agree with the strategy determined by the polynomial $g_h$ in the classical game. For the remaining checks: when $\gamma = 0$ the commutation check passes by construction, and when $\gamma = 1$ the Magic Square check passes by Theorem~\ref{thm:ms-from-ac}; the consistency checks 5 and 7 pass with certainty because $\tau^W_{[\tr(g_\cdot(y)\, r_W) = \cdot]} \ot I$ coincides with $E^{(\mathsf{Pair},W),\omega}$, respectively with the embedded $\mathsf{Variable}_1$ and $\mathsf{Variable}_5$ measurements of Theorem~\ref{thm:ms-from-ac} (item~3 there). Hence the strategy has value $1$.
\end{proof}

We now state the main soundness property of the Pauli basis test; the statement is an adaptation of the self-testing theorem of~\cite{Natarajan2018NEEXP} (Theorem~6.4 there). Unlike Theorem~\ref{lem:ld-soundness}, no projectivity assumption is made on the strategy.

\begin{theorem}[Soundness of the Pauli basis test]\label{thm:pauli}
	\uses{def:pauli-question-distribution, def:pauli-win-predicate, def:admissible, def:tensor-product-value, def:EPR, lem:pauli-observable-expansion, def:povm-distance}
	There exists a function
	\[
		\delta_{\mathrm{qld}}(\eps, m, d, q) = a\,(md)^a \bigl( \eps^b + q^{-b} + 2^{-bmd} \bigr)
	\]
	for universal constants $a \ge 1$ and $0 < b < 1$ such that the following holds. For all admissible parameter tuples $\mathsf{qldparams} = (q,m,d)$ and for all strategies $\mathcal S = (\ket\psi, A, B)$ for the game $\mathfrak{G}^{\mathrm{Pauli}}_{\mathsf{qldparams}}$ that succeed with probability at least $1 - \eps$, there exist local isometries $\phi_{\mathrm A}\colon \hilb_{\mathrm A} \to \hilb_{\mathrm A'} \ot \hilb_{\mathrm A''}$ and $\phi_{\mathrm B}\colon \hilb_{\mathrm B} \to \hilb_{\mathrm B'} \ot \hilb_{\mathrm B''}$, where $\ket\psi \in \hilb_{\mathrm A} \ot \hilb_{\mathrm B}$ and $\hilb_{\mathrm A''}, \hilb_{\mathrm B''} \cong (\C^q)^{\ot M}$ with $M = 2^m$, and a state $\ket{\mathrm{aux}} \in \hilb_{\mathrm A'} \ot \hilb_{\mathrm B'}$, such that:
	\begin{enumerate}
		\item $\bigl\| \phi_{\mathrm A} \ot \phi_{\mathrm B} \ket\psi - \ket{\mathrm{aux}} \ot \ket{\mathrm{EPR}_q}^{\ot M} \bigr\| \le \delta_{\mathrm{qld}}(\eps, m, d, q)$;
		% The paper here has the typo "phi_alice \ot phi_B"; both maps are the isometries above.
		\item letting $\tilde A^x_a = \phi_{\mathrm A} A^x_a \phi_{\mathrm A}^\dagger$ and $\tilde B^y_b = \phi_{\mathrm B} B^y_b \phi_{\mathrm B}^\dagger$, for $W \in \{X, Z\}$,
		\begin{align*}
			\tilde A^{(\mathsf{Pauli},W)}_u \ot I_{\mathrm{B'B''}} &\approx_{\delta_{\mathrm{qld}}} (\tau^W_u)_{\mathrm A''} \ot I_{\mathrm{A'B'B''}}\;,\\
			I_{\mathrm{A'A''}} \ot \tilde B^{(\mathsf{Pauli},W)}_u &\approx_{\delta_{\mathrm{qld}}} I_{\mathrm{A'A''B'}} \ot (\tau^W_u)_{\mathrm B''}\;,
		\end{align*}
		where the $\approx_{\delta_{\mathrm{qld}}}$ statements hold with respect to the state $\ket{\mathrm{aux}}_{\mathrm{A'B'}} \ot \ket{\mathrm{EPR}_q}^{\ot M}_{\mathrm{A''B''}}$ and the answer summation is over $u \in \F_q^M$.
	\end{enumerate}
\end{theorem}

The proof of Theorem~\ref{thm:pauli} is the adaptation, to low individual degree, of the analysis of the quantum low-degree test of Natarajan and Vidick; it is developed in Chapters~\ref{chap:qpbt-observables} and~\ref{chap:qpbt-combining} and concluded in Chapter~\ref{chap:qpbt-extraction}, where the argument is complete only modulo the unresolved divisibility obligation documented in \cite{gap:qpbt_ld-dimension-divisibility}. It relies on the classical soundness theorem (Theorem~\ref{lem:ld-soundness}) and on the rigidity of the Magic Square game (Theorem~\ref{thm:ms-rigidity}).

The strategies appearing in Lemma~\ref{lem:pauli-completeness} and in the conclusion of Theorem~\ref{thm:pauli} are phrased in terms of qudit Pauli measurements and maximally entangled states of $q$-dimensional qudits. For the intended application it is more convenient to work with qubits: since the field sizes $q$ used here are powers of $2$, the conclusions can be restated in terms of qubit EPR pairs and qubit Pauli measurements.

\begin{corollary}[Qubit form of the soundness of the Pauli basis test]\label{cor:pauli-binary}
	\uses{def:pauli-question-distribution, def:pauli-win-predicate, def:admissible, def:tensor-product-value, def:EPR, def:povm-distance}
	There exists a function
	\[
		\delta_{\mathrm{qld}}(\eps, m, d, q) = a\,(md)^a \bigl( \eps^b + q^{-b} + 2^{-bmd} \bigr)
	\]
	% The paper's displayed function here writes the argument order (eps, q, m, d); the
	% formula is the same, and its own item 1 reverts to (eps, m, d, q). See the remark below.
	for universal constants $a \ge 1$ and $0 < b < 1$ such that the following holds. For all admissible parameter tuples $\mathsf{qldparams} = (q,m,d)$ and for all strategies $\mathcal S = (\ket\psi, A, B)$ for the game $\mathfrak{G}^{\mathrm{Pauli}}_{\mathsf{qldparams}}$ that succeed with probability at least $1 - \eps$, there exist local isometries $\phi_{\mathrm A}\colon \hilb_{\mathrm A} \to \hilb_{\mathrm A'} \ot \hilb_{\mathrm A''}$ and $\phi_{\mathrm B}\colon \hilb_{\mathrm B} \to \hilb_{\mathrm B'} \ot \hilb_{\mathrm B''}$, where $\ket\psi \in \hilb_{\mathrm A} \ot \hilb_{\mathrm B}$ and $\hilb_{\mathrm A''}, \hilb_{\mathrm B''} \cong (\C^2)^{\ot M \log q}$ with $M = 2^m$, and a state $\ket{\mathrm{aux}} \in \hilb_{\mathrm A'} \ot \hilb_{\mathrm B'}$, such that:
	\begin{enumerate}
		\item $\bigl\| \phi_{\mathrm A} \ot \phi_{\mathrm B} \ket\psi - \ket{\mathrm{aux}} \ot \ket{\mathrm{EPR}_2}^{\ot M \log q} \bigr\| \le \delta_{\mathrm{qld}}(\eps, m, d, q)$;
		\item letting $\tilde A^x_a = \phi_{\mathrm A} A^x_a \phi_{\mathrm A}^\dagger$ and $\tilde B^y_b = \phi_{\mathrm B} B^y_b \phi_{\mathrm B}^\dagger$, for $W \in \{X, Z\}$,
		\begin{align*}
			\tilde A^{(\mathsf{Pauli},W)}_u \ot I_{\mathrm{B'B''}} &\approx_{\delta_{\mathrm{qld}}} (\sigma^W_u)_{\mathrm A''} \ot I_{\mathrm{A'B'B''}}\;,\\
			I_{\mathrm{A'A''}} \ot \tilde B^{(\mathsf{Pauli},W)}_u &\approx_{\delta_{\mathrm{qld}}} I_{\mathrm{A'A''B'}} \ot (\sigma^W_u)_{\mathrm B''}\;,
		\end{align*}
		where the $\approx_{\delta_{\mathrm{qld}}}$ statements hold with respect to the state $\ket{\mathrm{aux}}_{\mathrm{A'B'}} \ot \ket{\mathrm{EPR}_2}^{\ot M \log q}_{\mathrm{A''B''}}$ and the answer summation is over $u \in \F_q^M$. Here $\sigma^W_u$ denotes the tensor product of single-qubit Pauli measurements
		\[
			\bigotimes_{i=1}^{M} \bigotimes_{j=1}^{\log q} \sigma^W_{u_{ij}}\;,
		\]
		where $\kappa(u_i) = (u_{ij})_{1 \le j \le \log q}$ under the bijection $\kappa\colon \F_q \to \F_2^{\log q}$ of Chapter~\ref{chap:qpbt-algebra}.
	\end{enumerate}
	\end{enumerate}
\end{corollary}
\begin{proof}
	\uses{thm:pauli, lem:pauli-binary}
	By Lemma~\ref{lem:pauli-binary}, since $q$ is a power of $2$ there are local isometries that map $\ket{\mathrm{EPR}_q}^{\ot M}$ to $\ket{\mathrm{EPR}_2}^{\ot M \log q}$ and map the generalized Pauli measurements $\tau^W_u$ to the qubit tensor products $\bigotimes_{i=1}^M \bigotimes_{j=1}^{\log q} \sigma^W_{u_{ij}}$, where $\kappa(u_i) = (u_{i1},\ldots,u_{i \log q})$. Composing these isometries with those produced by Theorem~\ref{thm:pauli} gives the statement.
\end{proof}

\begin{remark}[Notational drift in the soundness functions]\label{rem:delta-qld-argument-order}
	The paper writes the soundness function of the Pauli basis test with two different argument orders: $\delta_{\mathrm{qld}}(\eps, m, d, q)$ in Theorem~\ref{thm:pauli} and Lemma~\ref{lem:delta-bound}, and $\delta_{\mathrm{qld}}(\eps, q, m, d)$ in the displayed function of Corollary~\ref{cor:pauli-binary}, whose own item~1 reverts to $\delta_{\mathrm{qld}}(\eps, m, d, q)$; the formula is the same throughout, and here the order $(\eps, m, d, q)$ is used everywhere. Note also two deliberate asymmetries with the classical soundness function of Theorem~\ref{lem:ld-soundness}: there the polynomial prefactor is $a(dmk)^a$ and the exponent satisfies $0 < b \le 1$, while in Theorems~\ref{thm:pauli} and Corollary~\ref{cor:pauli-binary} the prefactor is $a(md)^a$ and the exponent satisfies the strict inequality $0 < b < 1$.
\end{remark}

\section{Canonical parameters of the Pauli basis test}
% Paper label sec:qld-complexity kept for cross-reference fidelity (the complexity
% statements of that subsection are outside the scope of this development).
\label{sec:qld-complexity}

We specify a canonical setting of the parameter tuple $\mathsf{qldparams}$ as a function of an integer $R$, and bound the resulting soundness function. All logarithms are base $2$.

\begin{definition}[Canonical parameters of the Pauli basis test]\label{def:introparams}
	\uses{thm:pauli}
	Let $a, b$ be the universal constants of Theorem~\ref{thm:pauli}, and let $c$ be the smallest \emph{even} integer that is at least $(b+a)/b$. For every integer $R \ge 4$, define the tuple $\mathsf{introparams}(R) = (q, m, d)$ by
	\begin{itemize}
		\item $q = 2^k$ for $k = c \lceil \log \log R \rceil + 1$,
		\item $m = 2^j$, where $j$ is the unique integer with $2^j \le c \lceil \log R \rceil + 1 < 2^{j+1}$,
		\item $d = 1$.
	\end{itemize}
	The letter $k$ here denotes the exponent of the field size and is unrelated to the simultaneity parameter $k$ of the classical game. With this choice the Pauli basis test certifies the presence of an $M = 2^m$-qudit maximally entangled state of local dimension $q$, equivalently an $(M \log q)$-qubit EPR state, and the choice $d = 1$ runs the low individual degree test multilinearly.
\end{definition}

\begin{lemma}[Soundness bound for the canonical parameters]\label{lem:delta-bound}
	\uses{def:introparams, def:admissible, thm:pauli}
	For all integers $R \ge 4$, the parameter tuple $\mathsf{introparams}(R) = (q,m,d)$ is admissible (Definition~\ref{def:admissible}) and satisfies $2^m \ge R$. Furthermore, there exist universal constants $a' \ge 1$ and $0 < b' \le 1$ such that the function $\delta_{\mathrm{qld}}(\eps, m, d, q)$ of Theorem~\ref{thm:pauli} is at most
	\[
		a' \bigl( (\log R)^{a'} \cdot \eps^{b'} + (\log R)^{-b'} \bigr)\;.
	\]
\end{lemma}
\begin{proof}
	\uses{def:introparams, def:admissible, def:admissible-size, thm:pauli}
	Since $c$ is even, the exponent $k = c \lceil \log\log R \rceil + 1$ is odd, so $q = 2^k$ is an admissible field size; $m$ divides $q$ because $2^j \le c \lceil \log R \rceil + 1 \le 2 \log^c R \le 2^k$, so $j \le k$ and both are powers of $2$; and $d = 1 \ge 1$. Hence the tuple is admissible. Since $m = 2^j \ge (c/2) \log R$, we get $2^m \ge R^{c/2} \ge R$, using $c \ge 2$.

	For the soundness bound, write $\delta_{\mathrm{qld}}(\eps,m,d,q) = a(md)^a \eps^b + a(md)^a q^{-b} + a(md)^a 2^{-bmd}$ and use $d = 1$, $m \le 2c \log R$, and $q = 2^k \ge \log^c R$. The first term is at most $a(2c)^a (\log R)^a \eps^b$. The second term is at most $a(2c)^a (\log R)^{a - cb} \le a(2c)^a (\log R)^{-b}$, since $cb - a \ge b$ by the choice of $c$. For the third term, $m \ge (c/2) \log R \ge \log R$ gives $2^{-bm} \le R^{-b}$, so
	\[
		a(md)^a\, 2^{-bm}
		\le a(2c)^a (\log R)^a R^{-b}
		= a(2c)^a \bigl( (\log R)^{a+b} R^{-b} \bigr) (\log R)^{-b}
		\le a(2c)^a\, C\, (\log R)^{-b}\;,
	\]
	where $C = \sup_{R' \ge 4} (\log R')^{a+b} (R')^{-b}$ is finite --- the function is continuous in $R'$ and tends to $0$ as $R' \to \infty$ --- and depends only on the universal constants $a$ and $b$. Summing the three bounds, the statement follows with $a' = a(2c)^a (1 + C)$ and $b' = b$.
\end{proof}

\begin{remark}[A comparison of exponents in the source proof of Lemma~\ref{lem:delta-bound}]\label{rem:delta-bound-exponent-comparison}
	The source proof bounds the third term of $\delta_{\mathrm{qld}}$ by asserting $2^{-bmd} \le q^{-b}$ ``because $k \le m$'', comparing the field exponent $k = c \lceil \log\log R \rceil + 1$ with $m = 2^j$. The inequality $k \le m$ does not follow from Definition~\ref{def:introparams}: if the universal constants of Theorem~\ref{thm:pauli} were $a = 1$ and $b = 1/2$, then $c = 4$, and $R = 5$ gives $k = 9$ and $m = 8$. The proof above instead bounds $2^{-bm} \le R^{-b}$ directly from $m \ge (c/2) \log R \ge \log R$, which yields the same conclusion after enlarging the universal constant $a'$.
\end{remark}

\label{lem:ld-encoding-complexity}
Let $q$ be an admissible field size, and let $M = 2^m$ for some integer $m$.
The complexity of computing the evaluation of the low-degree encoding $g_a(x)$,
given $a \in \F_q^M$ and $x \in \F_q^m$ represented in binary, is $\poly(M,\log
q)$.
\end{lemma}
\begin{proof}
	Computing $g_a(x)$ requires computing the sum of products $a_y \cdot
  \ind_{m,y}(x)$ over all $y \in \{0,1\}^m$.
  Via \Cref{lem:efficient_arithmetic}, evaluating $\ind_{m,y}(x)$ takes time
  $\poly(m,\log q)$ because it requires performing $m$ multiplications of $\F_q$
  elements, and therefore the product $a_y \cdot \ind_{m,y}(x)$ requires
  $\poly(m,\log q)$ time.
  Computing the sum over all $y \in \{0,1\}^m$ requires $M \cdot \poly(m,\log q)
  = \poly(M,\log q)$ time, as claimed.
\end{proof}

Finally, for any $H \subseteq \F_q$ we define the \emph{decoding} map
$\coded_H(\cdot)$ which takes as input a polynomial $g : \F_q^m \to \F_q$ and
returns the following vector $a \in \F_q^M$: for all $y \in \{0,1\}^m$, if $g(y)
\in H$, then set $a_y = g(y)$, and otherwise set $a_y = 0$.
Note that for all $a \in H^M$ we have $\coded_H(g_a) = a$ where $g_a$ is the
low-degree encoding of $a$.
For notational brevity we often write $\coded(\cdot)$ to denote the boolean
decoding map $\coded_{\{0,1\}}(\cdot)$.

\subsection{Linear spaces and registers}
\label{sec:lin-reg}

For a set $V$, we write $\C^V$ for the complex vector space of dimension $|V|$.
The space $\C^V$ is endowed with a canonical orthonormal basis
$\{\ket{x}\}_{x\in V}$.
By ``a quantum state on $V$'' we mean a unit vector
\begin{equation*}
  \ket{\psi}_V \in \complex^V\;.
\end{equation*}
If $V = \bigoplus_{i=1}^k V_k$ is the direct sum of subspaces $V_k$ over $\F$,
then $\complex^V$ can be identified with $\bigotimes_{i=1}^k
\complex^{V_i}$, by the identification of $\ket{x_1 \oplus \dots \oplus
  x_k}$ with $\ket{x_1} \otimes \dots \otimes \ket{x_k}$.
As a special case, if $\{e_i\}$ is a basis of $V$ the decomposition $V =
\bigoplus_{i=1}^k ( \F e_i)$ yields the tensor product decomposition $\C^V =
\bigotimes_{i=1}^k \C^{\abs{\F}}$.
We sometimes refer to the spaces $\C^{\abs{\F}}$ as the ``qudits'' of $\C^V$ (or
of a state on it).

\begin{definition}
  \label{def:EPR}
  For a linear space $V$ over a finite field $\F$, define the \EPR state on $\C^V
  \otimes \C^V$ by
  \begin{equation*}
    \ket{\EPR}_V = \frac{1}{\sqrt{\abs{V}}} \sum_{x\in V}\ket {x}\otimes \ket{x}\;.
  \end{equation*}
  We also write $\ket{\EPR}_{\F_q}$ as $\ket{\EPR_q}$ and $\ket{\EPR_2}$ as
  $\ket{\EPR}$.
\end{definition}

\subsection{Measurements and observables}

Quantum measurements are modeled as positive operator-valued
measures (POVMs).
A POVM consists of a set of positive semidefinite operators $\{ M_a \}_{a\in S}$
indexed by outcomes $a\in S$ that satisfy the condition $\sum_a M_a = I$. If the latter condition is relaxed to $\sum_a M_a \leq I$ then we refer to $\{M_a\}$ as a \emph{sub-measurement}.
We sometimes use the same letter $M$ to refer to the collection of operators
defining the POVM.
The probability that the measurement returns outcome $a$ on state $\ket{\psi}$
is given by
\begin{equation*}
  \Pr(a) = \bra{\psi} M_a \ket{\psi}\;.
\end{equation*}
A POVM $M=\{M_a\}$ is said to be \emph{projective} if each operator $M_a$ is a
projector ($M_a^2 = M_a$). This automatically implies that operators
$M_a, M_b$ for distinct outcomes $a \neq b$ are orthogonal ($M_a M_b =
M_b M_a = 0$). An \emph{observable} is a unitary matrix.
A \emph{binary observable} is an observable $O$ such that $O^2 = \Id$, i.e.\ $O$
has eigenvalues in $\{-1,1\}$.

We follow the convention that subscripts of the measurement index
the outcome and superscripts of the measurement are used to index different
measurements.
For example, we use $\{M^x_{a,\, b}\}$ to represent a measurement indexed by $x$
whose outcome consists of two parts $a$ and $b$.
In this case, by slightly abusing the notation, we use $\{M^x_a\}$ and $\{M^x_b\}$
to denote
\begin{equation*}
  M^x_a = \sum_b M^x_{a,\, b}\;, \quad M^x_b = \sum_a M^x_{a,\, b}\;.
\end{equation*}
For any $x$, $\{M^x_a\}$ and $\{M^x_b\}$ are POVMs sometimes referred to as the
``marginals'' of $\{M^x_{a,\, b}\}$.

\begin{definition}
  \label{def:bracket}
  Let $\{M^x_a\}_{a\in A}$ be a family of POVMs indexed by $x\in \cal{X}$.
  Let $f:A\to B$ be an arbitrary function.
  We write $\bigl\{ M^x_{[f(\cdot)=b]} \bigr\}$ for the POVM derived from
  $\{M^x_a\}$ by applying the function $f$ before returning the outcome.
  More precisely,
\begin{equation*}
  M^x_{[f(\cdot) = b]} = \sum_{a : f(a)=b} M^x_a\;.
\end{equation*}
If $b$ is not in the image of $f$, then we define $M^x_{[f(\cdot) = b]}$ to be
$0$. In cases where the outcome $a$ has a natural interpretation as a tuple $(a_1,\ldots,a_k)$ we sometimes slightly abuse notation and write $M^x_{[a_i=b]}$ for some $i\in \{1,\ldots,k\}$ to denote 
\[ M^x_{[a_i=b]} \,=\,\sum_{(a_1,\ldots,a_k):\,a_i=b} M^x_{(a_1,\ldots,a_k)}\;.\]
\end{definition}

We will make frequent use of Naimark dilation. In our setting, it can be formulated as follows. For a proof, see~\cite[Theorem 5.1]{ML20}

\begin{theorem}[Naimark dilation]\label{thm:naimark}
Let $\ket{\psi}$ be a state in $\mH_{\mathrm{A}} \ot \mH_{\mathrm{B}}$.
Let $A = \{A^x_a\}$ be a sub-measurement acting on $\mH_{\mathrm{A}}$
and $B=\{B^y_b\}$ be a sub-measurement acting on $\mH_{\mathrm{B}}$.
Then there exists
\begin{enumerate}
\item Hilbert spaces $\mH_{\mathrm{A}_{\mathsf{aux}}}$ and $\mH_{\mathrm{B}_{\mathsf{aux}}}$,
\item a state $\ket{\mathsf{aux}} \in \mH_{\mathrm{A}_{\mathsf{aux}}} \ot \mH_{\mathrm{B}_{\mathsf{aux}}}$,
\item and two measurements  $\widehat{A} = \{\widehat{A}^x_a\}$ and $\widehat{B}=\{\widehat{B}^y_b\}$
acting on $\mH_{\mathrm{A}} \ot \mH_{\mathrm{A}_{\mathsf{aux}}}$
and $\mH_{\mathrm{B}} \ot \mH_{\mathrm{B}_{\mathsf{aux}}}$,
respectively,
\end{enumerate}
such that the following is true.
If we write $\ket{\widehat{\psi}} = \ket{\psi} \otimes \ket{\mathsf{aux}}$,
then for all $x,y, a, b$,
 \begin{equation*}
 \bra{\psi} A^x_a \ot B^y_b \ket{\psi}
 = \bra{\widehat{\psi}} \widehat{A}^x_a \ot \widehat{B}^y_b \ket{\widehat{\psi}}.
 \end{equation*}
 In addition, $\ket{\mathsf{aux}}$ is a \emph{product state},
 meaning that we can write it as
 \begin{equation*}
 \ket{\mathsf{aux}}= \ket{\mathsf{aux}_{\mathrm{A}}} \ot \ket{\mathsf{aux}_{\mathrm{B}}},
 \end{equation*}
for $\ket{\mathsf{aux}_{\mathrm{A}}}$ in $\mH_{\mathrm{A}_{\mathsf{aux}}}$
and $\ket{\mathsf{aux}_{\mathrm{B}}}$ in $\mH_{\mathrm{B}_{\mathsf{aux}}}$.
\end{theorem}
