\section{Quantum registers and EPR states}
% Paper label sec:lin-reg kept for cross-reference fidelity.
\label{sec:lin-reg}

\begin{definition}[State space of a linear register]\label{def:lin-reg}
	\uses{def:complementary}
	For a set $V$, we write $\C^V$ for the complex vector space of dimension
	$|V|$, endowed with the canonical orthonormal basis
	$\{\ket{x}\}_{x \in V}$. A \emph{quantum state on $V$} is a unit vector
	$\ket{\psi}_V \in \C^V$. If $V = \bigoplus_{i=1}^k V_i$ is a direct sum of
	subspaces over $\F$, then $\C^V$ is identified with
	$\bigotimes_{i=1}^k \C^{V_i}$ by identifying
	$\ket{x_1 \oplus \dots \oplus x_k}$ with
	$\ket{x_1} \ot \dots \ot \ket{x_k}$. In particular, a basis $\{e_i\}$ of
	$V$ yields the decomposition $V = \bigoplus_{i=1}^k (\F e_i)$ and hence
	$\C^V = \bigotimes_{i=1}^k \C^{|\F|}$; the factors $\C^{|\F|}$ are called
	the \emph{qudits} of $\C^V$.
\end{definition}

\begin{definition}[EPR state]\label{def:EPR}
	\uses{def:lin-reg}
	For a linear space $V$ over a finite field $\F$, the \emph{EPR state} on
	$\C^V \ot \C^V$ is
	\[
		\ket{\mathrm{EPR}}_V
		= \frac{1}{\sqrt{|V|}} \sum_{x \in V} \ket{x} \ot \ket{x}\;.
	\]
	We write $\ket{\mathrm{EPR}_q}$ for $\ket{\mathrm{EPR}}_{\F_q}$ and
	$\ket{\mathrm{EPR}}$ for $\ket{\mathrm{EPR}_2}$.
\end{definition}

\section{Generalized Pauli observables}
% Paper label sec:generalized-pauli kept for cross-reference fidelity.
\label{sec:generalized-pauli}

\begin{definition}[Generalized Pauli observables]\label{def:generalized-pauli}
	\uses{def:subfield-trace, def:lin-reg}
	Let $p$ be a prime and $\omega = e^{2\pi i/p}$. The \emph{generalized Pauli
	observables over $\F_p$} are the unitaries on $\C^{\F_p}$ given by
	\begin{equation}\label{eq:pauli-fp}
		\sigma^X(a) = \sum_{j \in \F_p} \ket{j + a}\bra{j}
		\qquad \text{and} \qquad
		\sigma^Z(b) = \sum_{j \in \F_p} \omega^{bj} \ket{j}\bra{j}
	\end{equation}
	for $a, b \in \F_p$, with arithmetic over $\F_p$. For $q = p^k$, the
	\emph{generalized Pauli observables over $\F_q$} are the unitaries on
	$\C^{\F_q}$
	\[
		\tau^X(a) = \sum_{j \in \F_q} \ket{j + a}\bra{j}
		\qquad \text{and} \qquad
		\tau^Z(b) = \sum_{j \in \F_q} \omega^{\tr(bj)} \ket{j}\bra{j}
	\]
	for $a, b \in \F_q$, where $\tr$ here denotes $\tr_{q \to p}$
	(Definition~\ref{def:subfield-trace}); for admissible $q$ this agrees with
	the standing shorthand, $p = 2$, and $\omega = -1$, so that all phases are
	signs. All the $\tau^X$ operators commute with one another, as do all the
	$\tau^Z$ operators. Their common eigenbases consist of the vectors
	$\ket{e_W}$, labeled by $e \in \F_q$ and $W \in \{X, Z\}$, given by
	\[
		\ket{e_X} = \frac{1}{\sqrt{q}} \sum_{j \in \F_q}
		\omega^{-\tr(ej)} \ket{j}\;, \qquad
		\ket{e_Z} = \ket{e}\;;
	\]
	the Fourier transform
	\begin{equation}\label{eq:fourier-f}
		F = \frac{1}{\sqrt{q}} \sum_{a, b \in \F_q}
		\omega^{-\tr(ab)} \ket{a}\bra{b}
	\end{equation}
	maps the computational ($Z$) eigenbasis to the $X$ eigenbasis. We write
	$\{\tau^W_e\}_{e \in \F_q}$ for the projective measurement whose elements
	are the rank-one projectors onto the vectors of the $W$ eigenbasis. For
	systems of $n$ qudits, we write, for $W \in \{X,Z\}$ and $a \in \F_q^n$,
	\[
		\tau^W(a) = \tau^W(a_1) \ot \dots \ot \tau^W(a_n)\;, \qquad
		\ket{e_W} = \ket{(e_1)_W} \ot \dots \ot \ket{(e_n)_W}
	\]
	for $e \in \F_q^n$, with associated rank-one projectors $\tau^W_e$.
\end{definition}

\begin{lemma}[Product and twisted commutation relations]\label{lem:twisted-commutation}
	\uses{def:generalized-pauli, def:subfield-trace, def:dot-product-orthogonal}
	Let $q = p^k$, let $n \ge 1$ be an integer, and let $W \in \{X, Z\}$.
	\begin{enumerate}
		\item For all $a, a' \in \F_q$ and $b \in \F_p$,
		      \begin{equation}\label{eq:pauli-product-power}
			      \tau^W(a)\, \tau^W(a') = \tau^W(a + a')
			      \qquad \text{and} \qquad
			      \bigl(\tau^W(a)\bigr)^b = \tau^W(ab)\;;
		      \end{equation}
		      in particular $\bigl(\tau^W(a)\bigr)^p = \Id$, so each
		      $\tau^W(a)$ is a unitary with eigenvalues that are $p$-th roots
		      of unity.
		\item For all $a, b \in \F_q^n$,
		      % Paper equation label kept on the display it names.
		      \begin{equation}\label{eq:twisted-fq}
			      \tau^X(a)\, \tau^Z(b)
			      = \omega^{-\tr(a \cdot b)}\, \tau^Z(b)\, \tau^X(a)\;,
		      \end{equation}
		      where $a \cdot b = \sum_{i=1}^n a_i b_i \in \F_q$. The case
		      $q = p$, $n = 1$ reads
		      \begin{equation}\label{eq:twisted-fp}
			      \sigma^X(a)\, \sigma^Z(b)
			      = \omega^{-ab}\, \sigma^Z(b)\, \sigma^X(a)
			      \qquad \text{for all } a, b \in \F_p\;.
		      \end{equation}
	\end{enumerate}
\end{lemma}
\begin{proof}
	\uses{def:generalized-pauli, def:subfield-trace}
	All identities are verified on computational basis states. For the product
	relations with $W = X$, shifting twice by $a'$ and $a$ equals shifting by
	$a + a'$; with $W = Z$, the phases $\omega^{\tr(aj)}\omega^{\tr(a'j)}$
	combine by $\F_q$-linearity of the trace, and the power relation follows by
	iterating. For the scalar twisted commutation,
	$\tau^X(a)\tau^Z(b)\ket{j} = \omega^{\tr(bj)}\ket{j + a}$, while
	$\tau^Z(b)\tau^X(a)\ket{j} = \omega^{\tr(b(j+a))}\ket{j + a} =
	\omega^{\tr(ab)}\,\omega^{\tr(bj)}\ket{j + a}$. The multi-qudit relation
	follows by applying the scalar relation factor by factor and summing the
	exponents, using $\tr(a \cdot b) = \sum_i \tr(a_i b_i)$. For $q = p$ the
	trace is the identity map, which gives \eqref{eq:twisted-fp}.
\end{proof}

\begin{lemma}[Fourier cancellation over a subspace]\label{lem:cancellation}
	\uses{def:dot-product-orthogonal, def:subfield-trace}
	Let $V$ be a subspace of $\F_q^k$ and let $\omega = e^{2\pi i/p}$, where
	$p$ is the characteristic of $\F_q$ and $\tr = \tr_{q \to p}$. For all
	$v \notin V^\perp$,
	\[
		\E_{\bu \sim V}\, \omega^{\tr(\bu \cdot v)} = 0\;,
	\]
	where the expectation is over a uniformly random vector $\bu$ in $V$.
\end{lemma}
\begin{proof}
	This is Fact 3.2 of \cite{Natarajan2018NEEXP}. Since $v \notin V^\perp$,
	the $\F_q$-linear functional $u \mapsto u \cdot v$ is not identically zero
	on $V$, hence surjective onto $\F_q$; composing with the nonzero map $\tr$
	shows that there is $u_0 \in V$ with $\tr(u_0 \cdot v) \neq 0$. Writing $C$
	for the expectation, translation invariance of the uniform distribution on
	$V$ gives
	$C = \E_{\bu \sim V}\, \omega^{\tr((\bu + u_0) \cdot v)}
	= \omega^{\tr(u_0 \cdot v)}\, C$, and $\omega^{\tr(u_0 \cdot v)} \neq 1$
	forces $C = 0$.
\end{proof}

\begin{lemma}[Fourier expansion of Pauli observables]\label{lem:pauli-observable-expansion}
	\uses{def:generalized-pauli, def:subfield-trace}
	For every integer $n \ge 1$, all $W \in \{X, Z\}$, and all $a \in \F_q^n$,
	% Paper equation label kept on the display it names.
	\begin{equation}\label{eq:pauli-obs-proj}
		\tau^W(a) = \sum_{b \in \F_q^n} \omega^{\tr(a \cdot b)}\, \tau^W_b\;,
	\end{equation}
	and conversely
	\begin{equation}\label{eq:pauli-inversion-0}
		\E_{\ba \sim \F_q^n}\, \omega^{-\tr(\ba \cdot b)}\, \tau^W(\ba)
		= \sum_{b' \in \F_q^n} \E_{\ba \sim \F_q^n}\,
		\omega^{\tr(\ba \cdot (b' - b))}\, \tau^W_{b'}
		= \tau^W_b\;.
	\end{equation}
\end{lemma}
\begin{proof}
	\uses{def:generalized-pauli, lem:cancellation}
	Each $\ket{b_W}$ is an eigenvector of $\tau^W(a)$ with eigenvalue
	$\omega^{\tr(a \cdot b)}$: for $W = Z$ this is immediate from the
	definition, and for $W = X$ it follows from the single-qudit computation
	$\tau^X(a)\ket{e_X} = \omega^{\tr(ae)}\ket{e_X}$, applied factor by factor.
	Expanding $\tau^W(a)$ in the orthonormal eigenbasis
	$\{\ket{b_W}\}_{b \in \F_q^n}$ gives the first display. For the inversion,
	substitute the first display and exchange the order of summation; by
	Lemma~\ref{lem:cancellation} applied with $V = \F_q^n$ (so that
	$V^\perp = \{0\}$), the inner expectation vanishes unless $b' = b$, where
	it equals $1$.
\end{proof}

Since only admissible field sizes $q = 2^k$ arise in the Pauli basis test, the
maximally entangled state $\ket{\mathrm{EPR}_q}$ and the qudit Pauli
projectors are isomorphic to tensor products of qubit EPR states
$\ket{\mathrm{EPR}_2}$ and qubit Pauli projectors. This is the content of the

    E^{(\ALine,W),\, \line}_{\, f}
    & = \tau^W_{[(g_{\cdot})|_\line = f]} \otimes I\;,\\
    E^{(\DLine,W),\, \line}_{\, f}
    & = \tau^W_{[(g_{\cdot})|_\line = f]} \otimes I\;,\\    
    E^{(\Pauli,W)}_{\, a}
    & = \tau^W_{a} \otimes I\;.
  \end{align*}
  Here, the bracket notation used to post-process measurement outcomes is
  defined in \Cref{def:bracket}.
  Thus, for example, the measurement on question $((\Point,W),y)$ corresponds to
  first performing the measurement $\{\tau^W_h\}_{h \in \F_q^M}$, receiving an
  outcome $h \in \F_q^M$, and then outputting the value $a = g_{h}(y)$.

  For $\ALine$ and $\DLine$ questions, the question content $\line$ denotes
  either an axis-parallel line $\line(u_0,e_i)$ for some $i \in
  \{1,2,\ldots,m\}$, or a diagonal line $\line(u_0,v')$ for some $v' \in
  \F_q^m$.
  As described at the beginning of \Cref{sec:qld-game}, axis-parallel lines are
  specified by pairs $(u_0,s) \in \F_q^m \times \F_q$ and diagonal lines are
  specified by triples $(u_0,s,v) \in \F_q^m \times \F_q \times \F_q^m$.
  The measurement on question $((\ALine,W),\line)$, for example, corresponds to
  first performing the measurement $\{\tau^W_h\}_{h \in \F_q^M}$ to get an
  outcome $h \in \F_q^M$, and reporting the univariate polynomial $f_\line(t) =
  g_{h}(u_0 + te_i)$ where $\line$ is specified by $(u_0,s)$ and $i = \chi(s)$.



  Next we specify the POVMs associated with questions of type $\Constraint$,
  $\Variable$, and $\Pair$.
  Questions with these question types have a question content that is a tuple
  $\omega= (u_\xpt, u_\zpt, r_\xpt, r_\zpt)\in (\F_q^m)^2 \times \F_q^2$.
  Given such a tuple, consider the two $\F_2$-valued POVMs $A=\{A_b\}_{b \in
    \F_2}$ and $B=\{B_b\}_{b \in \F_2}$ defined as
  \begin{align}
    A_b & = \tau^X_{[\tr(g_{\cdot}(u_X)\, r_\xpt) = b]} \otimes I\;,\label{eq:gonna-expand-A}\\
    B_b & = \tau^Z_{[\tr(g_{\cdot}(u_Z)\, r_\zpt) = b]} \otimes I\;.\label{eq:gonna-expand-B}
  \end{align}
  We would like to determine when the two observables $\mathcal{O}_A = A_0 -
  A_1$ and $\mathcal{O}_B = B_0 - B_1$ commute or anti-commute.
  Towards this we derive alternative expressions for these observables from
  which their commutativity becomes plain from inspection.
  We begin by inspecting the first matrices on the right-hand sides of
  Equations~\eqref{eq:gonna-expand-A} and~\eqref{eq:gonna-expand-B}:
  \begin{align}
  \tau^W_{[\tr(g_{\cdot}(u_W)\, r_W) = b]}
  &= \sum_{h : \tr(g_{h}(u_W)\, r_W) = b} \tau^W_h\nonumber\\
  &= \sum_{h : \tr((h\, \cdot\, \ind_{m}(u_W)) \cdot r_W ) = b} \tau^W_h\;,\label{eq:expand-with-dot-product}
  \end{align}
  where~\eqref{eq:expand-with-dot-product}
  follows by  Definition~\ref{eq:low-degree-encoding-definition}.
  As a result,
  \begin{align}
&  \tau^W_{[\tr(g_{\cdot}(u_W)\, r_W) = 0]}
  -   \tau^W_{[\tr(g_{\cdot}(u_W)\, r_W) = 1]} \notag \\
  & = \sum_{h : \tr((h\, \cdot\, \ind_{m}(u_W)) \cdot r_W ) = 0} \tau^W_h
  	- \sum_{h : \tr((h\, \cdot\, \ind_{m}(u_W)) \cdot r_W ) = 1} \tau^W_h\nonumber\\
  & = \sum_{h} (-1)^{\tr((h\, \cdot\, \ind_{m}(u_W)) \cdot r_W )} \tau^W_h\nonumber\\
  & = \tau^W(\ind_{m}(u_W)r_W)\;,\label{eq:finally-got-an-observable}
  \end{align}
  where the last step uses~\eqref{eq:pauli-obs-proj}.
  As a result, Equation~\eqref{eq:finally-got-an-observable}
  and Equations~\eqref{eq:gonna-expand-A} and~\eqref{eq:gonna-expand-B} imply that
  \begin{equation*}
  \mathcal{O}_A = \tau^X(\ind_{m}(u_X)r_X) \otimes I,\quad
  \mathcal{O}_B = \tau^Z(\ind_{m}(u_Z)r_Z) \otimes I\;.
  \end{equation*}
  Now, let $\gamma = \tr((\ind_{m}(u_X)r_X) \cdot (\ind_{m}(u_Z)r_Z)) \in \F_2$,
  as in Equation~\eqref{eq:gamma-value}.
  Then by Equation~\eqref{eq:twisted-fq},
  \begin{equation*}
  \mathcal{O}_A \mathcal{O}_B = (-1)^{\gamma} \mathcal{O}_B \mathcal{O}_A\;.
  we can write the $(\Point, W)$ measurement as follows: 
  \begin{equation*}
  E^{(\Point,W),\, y}_{[\tr(\,\cdot\, r_W) = a_{\overline{w}}]}
  = \tau^W_{[\tr(g_{\cdot}(y)r_W) = a_{\overline{w}}]} \otimes I
  = E^{(\Pair, W), \omega}_{a_{\overline{w}}} \otimes I.
  \end{equation*}
  As a result, due to the consistency of the $(\Pair, W)$ measurement, the
  consistency check is passed with probability~$1$.
  On the other hand, if $\gamma \neq 0$, then the strategy passes the Magic
  Square check by Theorem~\ref{thm:ms-from-ac}.
  As for the consistency check in Item~\ref{item:magic-square-consistency}, we
  can write the $(\Point, X)$ measurement as follows:
  \begin{equation*}
  E^{(\Point,X),\, y}_{[\tr(\,\cdot\, r_X) = a_{\overline{w}}]}
  = \tau^X_{[\tr(g_{\cdot}(y)r_X) = a_{\overline{w}}]} \otimes I
  = E^{\Variable_1,\, \omega}_{a_{\overline{w}}} \otimes I,
  \end{equation*}
  where the last step is by Theorem~\ref{thm:ms-from-ac}.
  As these measurements are consistent, this test is passed with
  probability~$1$.
\end{proof}





\paragraph{Soundness of the Pauli basis test.} 
We state the soundness properties of the Pauli basis test.
The following is an adaptation of the self-testing statement in~\cite[Theorem
6.4]{NW19}.

\begin{theorem}
  \label{thm:pauli}
There exists a function 
\[\delta_{\qld}(\eps,m,d,q) = a(md)^a(\eps^b + q^{-b} + 2^{-bmd})\]
 for universal constants $a \geq 1$ and $0 < b < 1$ such that the following holds. For all admissible parameter tuples $\qldparams = (q,m,d)$ and for all strategies $\strategy = (\ket{\psi},A,B)$ for the game $\game^\pauli_\qldparams$ that succeed with probability at least $1 - \eps$, there exist local isometries $\phi_\alice: \mH_\alice \to \mH_{\alice'} \otimes \mH_{\alice''},\phi_\bob: \mH_\bob \to \mH_{\bob'} \otimes \mH_{\bob''}$ (where $\ket{\psi} \in \mH_\alice \otimes \mH_\bob$ and $\mH_{\alice''},\mH_{\bob''} \cong (\C^q)^{\otimes M}$ with $M = 2^m$) and a state $\ket{\aux} \in \mH_{\alice'} \otimes \mH_{\bob'}$ such that 
\begin{enumerate}
    \item $\left \| \phi_\alice \otimes \phi_B \ket{\psi} - \ket{\aux} \otimes \ket{\EPR_q}^{\otimes M}  \right \| \leq \delta_{\qld}(\eps,m,d,q)$,
    \item Letting $\tilde{A}^x_a = \phi_A\, A^x_a \, \phi_A^\dagger$ and $\tilde{B}^y_b = \phi_B B^y_b \phi_B^\dagger$, we have for $W \in \{X,Z\}$
    \begin{gather*}
        \tilde{A}^{(\pauli,W)}_u \otimes I_{\bob'\bob''} \approx_{\delta_{\qld}} (\tau^W_u)_{\alice''} \otimes I_{\alice' \bob' \bob''} \\
        I_{\alice'\alice''} \otimes \tilde{B}^{(\pauli,W)}_u    \approx_{\delta_{\qld}} I_{\alice' \alice'' \bob'} \otimes (\tau^W_u)_{\bob''}\;,
    \end{gather*}
    where the $\approx_{\delta_{\qld}}$ statement holds with respect to the state $\ket{\aux}_{\alice'\bob'} \otimes \ket{\EPR_q}^{\otimes M}_{\alice''\bob''}$ and the answer summation is over $u \in \F_q^M$.
\end{enumerate}
\end{theorem}

We provide a proof of \Cref{thm:pauli} in \Cref{sec:qld-analysis}. 


The strategies described in the proof of \Cref{lem:pauli-completeness} and in the conclusion of \Cref{thm:pauli} are described in terms of qudit Pauli measurements and maximally entangled states defined over $q$-dimensional qudits. 
However, it is more convenient for our application of the Pauli basis test to
instead deal with \emph{qubits}.
In particular, we use the Pauli basis test in the ``introspection game'' of
Section~\ref{sec:introspection}, where the players are commanded to sample
questions according to a sampler $\sampler$ of a normal form verifier.

